const money = ec.user.hasPermission('TIME_ENTRY_RATE')
if (action === 'rates' && !money) { ec.message.addError(L('Only those who manage money update rates')); return }
if (action === 'move' && !value) { ec.message.addError(L('Choose the work item')); return }
if (action === 'billable' && !['Y', 'N'].includes(value)) { ec.message.addError(L('Billable or not')); return }
if (action === 'workType' && value) {
    const type = ec.entity.find('moqui.basic.Enumeration').condition('enumId', value).useCache(true).one()
    if (!type || type.enumTypeId !== 'WorkType') { ec.message.addError(L('Not a work type')); return }
}
const rows = Array.from(ec.service.sync().name('ironstone.projects.TimeServices.find#TimeEntryRows').parameters({list: 'all', timeEntryIds: ids, pageNoLimit: true}).call()?.rowList || [])
const byId = {}
for (const row of rows) byId[row.timeEntryId] = row
const reasons = []
const refuse = (id, reason) => { failedCount++; if (reasons.length < 5) reasons.push(id + ': ' + reason) }
for (const id of ids) {
    const row = byId[id]
    if (!row) { refuse(id, L('not available')); continue }
    if (row.invoiced) { refuse(id, L('invoiced')); continue }
    if (row.running) { refuse(id, L('the timer runs on it')); continue }
    const moneyChange = action === 'rates' || (action === 'billable' && money)
    if (!row.canEdit && !moneyChange) { refuse(id, row.locked ? L('its week is submitted') : L('not yours to change')); continue }
    ec.message.pushErrors()
    try {
        const call = (name, parameters) => {
            ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        }
        if (action === 'move') {
            call('ironstone.projects.TimeServices.check#TimeItem', {workEffortId: value})
            call('mantle.work.TimeServices.store#TimeEntry', {timeEntryId: id, workEffortId: value, rateTypeEnumId: row.rateTypeEnumId || 'RatpStandard'})
        } else if (action === 'workType') call('mantle.work.TimeServices.store#TimeEntry', {timeEntryId: id, workTypeEnumId: value || null,
            rateTypeEnumId: row.rateTypeEnumId || 'RatpStandard'})
        else if (action === 'billable') call('mantle.work.TimeServices.store#TimeEntry', {timeEntryId: id, rateTypeEnumId: value === 'N' ? 'RatpNoCharge' : 'RatpStandard'})
        else if (action === 'rates') call('mantle.work.TimeServices.get#TimeEntryRate', {timeEntryId: id, resetRates: true})
        else if (action === 'delete') call('mantle.work.TimeServices.delete#TimeEntry', {timeEntryId: id})
        doneCount++
    } catch (err) {
        const reason = String(err && err.message ? err.message : err).trim()
        ec.logger.warn(`Time entries: ${action} of ${id} was not done: ${reason}`)
        refuse(id, reason)
