        if (!(id in names)) { const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
            names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || id) : id }
        return names[id]
    }
    const sheets = {}
    const sheetOf = (id) => { if (!id) return null; if (!(id in sheets)) sheets[id] = ec.entity.find('mantle.work.time.Timesheet').condition('timesheetId', id).one(); return sheets[id] }
    const entries = Array.from(ec.entity.find('mantle.work.time.TimeEntry').condition('workEffortId', workEffortId).orderBy('-fromDate').limit(1000).list())
    // the worker amount of an employee's time (employed on its date or now) is pay: only with PAYROLL_VIEW, asked once
    const payHidden = new Set(money ? Array.from(ec.service.sync().name('mantle.humanres.EmploymentServices.get#PayRateAccess')
            .parameters({entryList: entries.slice(0, 100).map((entry) => ({key: entry.timeEntryId, partyId: entry.partyId,
                date: entry.fromDate ?? entry.thruDate}))}).call()?.hiddenKeys || []) : [])
    for (const entry of entries) {
        const hours = Number(String(entry.hours ?? 0))
        total += hours; count++
        const person = people[entry.partyId] || (people[entry.partyId] = {name: nameOf(entry.partyId), hours: 0})
        person.hours += hours
        if (rows.length >= 100) continue
        const sheet = sheetOf(entry.timesheetId)
        const status = entry.thruDate == null ? L('Running') : (entry.invoiceId || entry.vendorInvoiceId) ? L('Invoiced')
                : sheet?.statusId === 'TmshApproved' ? L('Approved') : sheet?.statusId === 'TmshCompleted' ? L('Submitted') : L('Open')
        const client = entry.clientHourRate == null ? null : hours * Number(String(entry.clientHourRate))
        const vendor = entry.vendorHourRate == null || payHidden.has(entry.timeEntryId) ? null : hours * Number(String(entry.vendorHourRate))
        rows.push({timeEntryId: entry.timeEntryId, personName: nameOf(entry.partyId), dateText: fmt(Number(String(entry.fromDate)), 'EEE, MMM d'),
            hoursText: n(hours), workTypeLabel: entry.workTypeEnumId ? (types[entry.workTypeEnumId] || entry.workTypeEnumId) : '',
            billableText: entry.rateTypeEnumId === 'RatpNoCharge' ? L('Not billable') : L('Billable'), comments: entry.comments || '', statusLabel: status,
