    if (!Array.from(info.clientProjectIds || []).map(String).includes(String(workEffortId))
            || !Array.from(info.shareHoursProjectIds || []).map(String).includes(String(workEffortId))) return
    const items = {}
    for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', workEffortId).condition('workEffortTypeEnumId', 'WetTask')
            .condition('visibilityEnumId', 'in', ['WevAllUsers', 'WevGeneral']).selectField('workEffortId').selectField('workEffortName').list())
        items[row.workEffortId] = row.workEffortName || ''
    const itemIds = Object.keys(items)
    const weeks = {}, byItem = {}
    let total = 0, count = 0
    const sheets = {}
    const sheetApproved = (id) => {
        if (!id) return false
        if (!(id in sheets)) sheets[id] = ec.entity.find('mantle.work.time.Timesheet').condition('timesheetId', id).selectField('statusId').one()?.statusId === 'TmshApproved'
        return sheets[id]
    }
    const mondayOf = (millis) => {
        const day = ec.l10n.format(new Date(millis), 'yyyy-MM-dd')
        const date = new Date(day + 'T12:00:00Z')
        const iso = date.getUTCDay() === 0 ? 7 : date.getUTCDay()
        date.setUTCDate(date.getUTCDate() - (iso - 1))
        return date.toISOString().substring(0, 10)
    }
    for (let i = 0; i < itemIds.length; i += 1000) {
        for (const entry of ec.entity.find('mantle.work.time.TimeEntry').condition('workEffortId', 'in', itemIds.slice(i, i + 1000))
                .condition('thruDate', 'is-not-null', null).selectField('timeEntryId').selectField('workEffortId').selectField('fromDate')
                .selectField('hours').selectField('rateTypeEnumId').selectField('timesheetId').selectField('invoiceId').limit(50000).list()) {
            if (entry.rateTypeEnumId === 'RatpNoCharge' || entry.fromDate == null) continue
            if (!entry.invoiceId && !sheetApproved(entry.timesheetId)) continue
            const hours = Number(String(entry.hours ?? 0))
            if (!(hours > 0)) continue
            const week = mondayOf(Number(String(entry.fromDate)))
            const weekEntry = weeks[week] || (weeks[week] = {hours: 0, items: {}})
            weekEntry.hours += hours
            weekEntry.items[entry.workEffortId] = (weekEntry.items[entry.workEffortId] || 0) + hours
            byItem[entry.workEffortId] = (byItem[entry.workEffortId] || 0) + hours
            total += hours; count++
        }
