        const weekText = ec.resource.expand('Week of ${day}', '', {day: ec.l10n.format(new Date(week + 'T12:00:00Z'), 'MMM d, yyyy')})
        for (const id of Object.keys(weeks[week].items).sort((a, b) => weeks[week].items[b] - weeks[week].items[a] || a.localeCompare(b)))
            weekRows.push({weekStart: week, weekText: weekText, workEffortId: id, itemText: itemText(id), url: itemUrl(id), hoursText: n(weeks[week].items[id]),
                weekTotalText: n(weeks[week].hours)})
    }
    const itemRows = Object.keys(byItem).sort((a, b) => byItem[b] - byItem[a] || a.localeCompare(b))
            .map((id) => ({workEffortId: id, itemText: itemText(id), url: itemUrl(id), hoursText: n(byItem[id])}))
    clientHours = {shared: true, weekRows: weekRows, itemRows: itemRows, totalText: n(total), entryCount: count, weekCount: Object.keys(weeks).length}
} catch (err) {
